const money=(cents:number)=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(cents/100);
const amount=(value:string)=>Math.round(Number(value.replace(',','.'))*100);
const percent=(value:number|null|undefined)=>value==null?'—':new Intl.NumberFormat('pt-BR',{maximumFractionDigits:2}).format(value)+'%';
const today=()=>{const parts=new Intl.DateTimeFormat('en-CA',{timeZone:'America/Sao_Paulo',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date());return ['year','month','day'].map(type=>parts.find(part=>part.type===type)?.value).join('-');};
const currentMonth=()=>today().slice(0,7);
const dateLabel=(value:string)=>value?value.slice(0,10).split('-').reverse().join('/'):'—';
const monthLabel=(value:string)=>new Date(value+'-15T12:00:00').toLocaleDateString('pt-BR',{month:'short',year:'numeric'});
const csvCell=(value:unknown)=>{let text=String(value??'');if(/^[\s]*[=+@\-]/.test(text))text="'"+text;return '"'+text.replaceAll('"','""')+'"';};
function downloadCsv(name:string,rows:unknown[][]){const blob=new Blob(['\uFEFF'+rows.map(row=>row.map(csvCell).join(';')).join('\r\n')],{type:'text/csv;charset=utf-8'});const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download=name;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}

type Option={value:string;label:string};
type Field={key:string;label:string;showWhen?:(values:FormValues)=>boolean;type?:'currency'|'text'|'date'|'month'|'number'|'textarea'|'select';options?:Option[];value?:string;required?:boolean;help?:string;full?:boolean;min?:string;max?:string;step?:string};
type FormValues=Record<string,string>;
function FinanceModal({title,description,children,onClose}:{title:string;description?:string;children:ReactNode;onClose:()=>void}){
  const ref=useRef<HTMLDialogElement>(null);
  useEffect(()=>{const previous=document.activeElement as HTMLElement;const overflow=document.body.style.overflow;document.body.style.overflow='hidden';ref.current?.showModal();return()=>{document.body.style.overflow=overflow;if(previous?.isConnected)previous.focus();};},[]);
  return <dialog ref={ref} className="pf-modal" aria-label={title} onCancel={e=>{e.preventDefault();onClose();}}><header><div><span className="ps-overline">EME SELECT · FINANCEIRO</span><h2>{title}</h2></div><button className="ps-icon" onClick={onClose} aria-label="Fechar formulário"><X size={20}/></button></header><div className="pf-modal-body">{description&&<p className="pf-modal-description">{description}</p>}{children}</div></dialog>;
}
function FinanceForm({fields,onSubmit,onClose,onReload,submitLabel='Salvar registro',children}:{fields:Field[];onSubmit:(values:FormValues)=>Promise<void>;onClose:()=>void;onReload?:()=>Promise<boolean>;submitLabel?:string;children?:ReactNode}){
  const [values,setValues]=useState<FormValues>(()=>Object.fromEntries(fields.map(field=>[field.key,field.value??'']))),[busy,setBusy]=useState(false),[error,setError]=useState('');
  async function submit(event:FormEvent){event.preventDefault();setBusy(true);setError('');try{await onSubmit(values);}catch(error){setError((error as Error).message);}finally{setBusy(false);}}
  return <form className="pf-form" onSubmit={submit}><div className="pf-form-grid">{fields.filter(field=>!field.showWhen||field.showWhen(values)).map((field,index)=><label key={field.key} className={'pf-field'+(field.full?' pf-field--full':'')}>{field.label}{field.type==='currency'?<CurrencyInput label={field.label} value={values[field.key]===''?null:Number(values[field.key])} allowNegative={field.min===undefined} required={field.required!==false} onChange={v=>setValues(previous=>({...previous,[field.key]:v==null?'':String(v)}))}/>:field.type==='select'?<select aria-label={field.label} value={values[field.key]} required={field.required!==false} onChange={event=>setValues(previous=>({...previous,[field.key]:event.target.value}))}><option value="">{field.required===false?'Sem vínculo / não informado':'Selecione'}</option>{field.options?.map(option=><option key={option.value} value={option.value}>{option.label}</option>)}</select>:field.type==='textarea'?<textarea aria-label={field.label} value={values[field.key]} rows={3} maxLength={1200} required={field.required!==false} onChange={event=>setValues(previous=>({...previous,[field.key]:event.target.value}))}/>:<input aria-label={field.label} autoFocus={index===0} value={values[field.key]} type={field.type??'text'} min={field.min} max={field.max} step={field.step??(field.type==='number'?'0.01':undefined)} maxLength={240} required={field.required!==false} onChange={event=>setValues(previous=>({...previous,[field.key]:event.target.value}))}/>} {field.help&&<small>{field.help}</small>}</label>)}</div>{children}{error&&<div className="pt-error" role="alert"><p>{error}</p>{onReload&&<button type="button" className="ps-text-button" disabled={busy} onClick={async()=>{setBusy(true);if(await onReload())setError('Dados atualizados. Seus campos foram preservados; confira e tente salvar novamente.');setBusy(false);}}>Atualizar dados do financeiro</button>}</div>}<div className="pf-form-footer"><button type="button" disabled={busy} className="ps-button" onClick={onClose}>Cancelar</button><button className="ps-button ps-button--primary" disabled={busy}>{busy?'Salvando…':submitLabel}<Check size={16}/></button></div></form>;
}
function Metric({label,value,note,negative=false}:{label:string;value:string;note:string;negative?:boolean}){return <article className="pf-metric"><span>{label}</span><strong className={negative?'pf-negative':undefined}>{value}</strong><small>{note}</small></article>;}
function Empty({title,description,action,onAction}:{title:string;description:string;action?:string;onAction?:()=>void}){return <div className="pf-empty"><Wallet size={28}/><h3>{title}</h3><p>{description}</p>{action&&<button className="ps-button ps-button--primary" onClick={onAction}>{action}<Plus size={16}/></button>}</div>;}
function Notice({children,warning=false}:{children:ReactNode;warning?:boolean}){return <div className={'pf-callout'+(warning?' pf-callout--warning':'')}><ShieldCheck size={17}/><p>{children}</p></div>;}

type FinanceHistory={id:string|number;action:string;detail?:string;author?:string;created_at?:string;createdAt?:string};
type Snapshot={version:number;state:FinanceState;history:FinanceHistory[];members?:Assignee[];properties?:{id:string;title:string}[]};
type ModalState={kind:'contribution'|'account'|'entry'|'settle'|'cancel'|'recurrence'|'generate'|'operation'|'cancel-operation'|'partner'|'settings'|'adjustment'|'cancel-adjustment'|'distribution-plan'|'repayment-plan';id?:string;category?:string;partnerId?:string;returnToSettlementId?:string;returnToContribution?:{category:string;partnerId:string}};
const tabs=[['overview','Visão geral'],['simulation','Comissão e caixa'],['entries','Lançamentos'],['accounts','Contas'],['recurrences','Recorrências'],['operations','Operações e corretores'],['agreements','Acordos de comissão'],['partners','Sócios e planejamento'],['reports','DRE e projeções']] as const;
const financeGroups=[{name:'Resumo',ids:['overview','reports']},{name:'Caixa',ids:['entries','accounts','recurrences']},{name:'Negócios e comissões',ids:['operations','agreements','simulation']},{name:'Sócios',ids:['partners']}];
const categoryLabel=(id:string)=>FINANCE_CATEGORIES.find(category=>category.id===id)?.label??id;
const partnerMovement=(category:string)=>['capital_in','loan_in','loan_repayment','partner_distribution','prolabore'].includes(category);
const actionLabel=(action:string)=>({'account.save':'Conta atualizada','entry.save':'Lançamento registrado','entry.settle':'Baixa registrada','entry.cancel':'Lançamento cancelado','recurrence.save':'Recorrência atualizada','recurrence.generate':'Competência gerada','operation.create':'Operação registrada','operation.cancel':'Operação cancelada','partner.save':'Sócio atualizado','settings.save':'Regras financeiras atualizadas','adjustment.save':'Ajuste de DRE registrado','adjustment.cancel':'Ajuste de DRE cancelado','distribution.plan':'Distribuição de lucros programada','repayment.plan':'Compensação de aportes programada'}[action]??action);
const entryDirection=(category:string)=>FINANCE_CATEGORIES.find(item=>item.id===category)?.direction;
const settlementAction=(category:string)=>category==='management_fee_retained'?'Registrar retenção':entryDirection(category)==='in'?'Receber':entryDirection(category)==='out'?'Pagar':'Registrar transferência';
const entryStatus=(status:string,category?:string)=>status==='cancelled'?'Cancelado':status==='settled'?(category==='management_fee_retained'?'Retido':entryDirection(category??'')==='in'?'Recebido':entryDirection(category??'')==='out'?'Pago':'Transferido'):(entryDirection(category??'')==='in'?'A receber':entryDirection(category??'')==='out'?'A pagar':'Em aberto');
const moneyField=(key:string,label:string,value?:number|null,help?:string):Field=>({key,label:label+' (R$)',type:'currency',min:'0',value:value==null?'':String(value/100),help});
const percentageField=(key:string,label:string,value?:number|null):Field=>({key,label:label+' (%)',type:'number',min:'0',max:'100',value:value==null?'':String(value/100)});
const dreRows:{key:keyof DreValues;label:string;total?:boolean}[]=[{key:'revenueCents',label:'Receita bruta da EME'},{key:'deductionsCents',label:'(−) Deduções da receita'},{key:'netRevenueCents',label:'Receita líquida',total:true},{key:'directCostCents',label:'(−) Comissões e custos diretos'},{key:'grossProfitCents',label:'Lucro bruto',total:true},{key:'operatingExpensesCents',label:'(−) Despesas operacionais e pró-labore'},{key:'operatingProfitCents',label:'Resultado operacional',total:true},{key:'financialIncomeCents',label:'(+) Receitas financeiras'},{key:'financialExpenseCents',label:'(−) Despesas financeiras'},{key:'incomeTaxCents',label:'(−) Tributos sobre o resultado'},{key:'netProfitCents',label:'Lucro líquido gerencial',total:true}];

export default function FinanceWorkspace({user,members:initialMembers,properties:initialProperties}:{user:TeamUser;members:Assignee[];properties:{id:string;title:string}[]}){
  const [snapshot,setSnapshot]=useState<Snapshot|null>(null),[loading,setLoading]=useState(true),[error,setError]=useState(''),[toast,setToast]=useState(''),[conflict,setConflict]=useState(false);
  const retryCommand=useRef<{fingerprint:string;body:{version:number;requestId:string;command:FinanceCommand}}|null>(null);
  const [tab,setTab]=useState<(typeof tabs)[number][0]>('overview'),[month,setMonth]=useState(currentMonth),[modal,setModal]=useState<ModalState|null>(null);
  const [entryScope,setEntryScope]=useState('month');
  const [query,setQuery]=useState(''),[categoryFilter,setCategoryFilter]=useState(''),[centerFilter,setCenterFilter]=useState(''),[entryFilter,setEntryFilter]=useState<'all'|'receivable'|'payable'|'settled'>('all');
  async function refresh(){setLoading(true);setError('');try{setSnapshot(await api<Snapshot>('/finance'));setConflict(false);return true;}catch(error){setError((error as Error).message);return false;}finally{setLoading(false);}}
  useEffect(()=>{if(user.role==='admin')void refresh();},[user.id,user.role]);
  useEffect(()=>{if(!toast)return;const timer=setTimeout(()=>setToast(''),6000);return()=>clearTimeout(timer);},[toast]);
  async function command(type:string,data:Record<string,unknown>,message='Registro salvo no financeiro.'){
    if(!snapshot)return;
    if(conflict)throw new Error('Os dados foram alterados por outra pessoa. Atualize os dados abaixo, confira os valores e salve novamente.');
    const fingerprint=JSON.stringify({type,data});
    const pending=retryCommand.current?.fingerprint===fingerprint?retryCommand.current:{fingerprint,body:{version:snapshot.version,requestId:crypto.randomUUID(),command:{type,data} as FinanceCommand}};
    retryCommand.current=pending;
    try{const updated=await api<Snapshot>('/finance/commands','POST',pending.body);retryCommand.current=null;setSnapshot(updated);setModal(null);setToast(message);}
    catch(error){if((error as {status?:number}).status===409){retryCommand.current=null;setConflict(true);}throw error;}
  }
  const state=snapshot?.state;
  const from=month+'-01',to=month+'-'+String(new Date(Number(month.slice(0,4)),Number(month.slice(5,7)),0,12).getDate()).padStart(2,'0');
  const members=snapshot?.members??initialMembers,properties=snapshot?.properties??initialProperties;
  const report=useMemo(()=>state?financeReport(state,{from,to,asOf:today()},members):null,[state,from,to,members]);
  const memberName=(id?:string|null)=>members.find(member=>member.id===id)?.name??(id?'Corretor cadastrado':'Não vinculado');
  const propertyName=(id?:string|null)=>properties.find(property=>property.id===id)?.title??(id?'Imóvel cadastrado':'Não vinculado');
  const accountName=(id?:string|null)=>state?.accounts.find(account=>account.id===id)?.name??'Sem conta vinculada';
  const centers=[...new Set(state?.entries.map(entry=>entry.costCenter).filter(Boolean)??[])];
  const entries=state?.entries.filter(entry=>(entryScope==='all'||entry.competenceDate.slice(0,7)===month)&&(!categoryFilter||entry.category===categoryFilter)&&(!centerFilter||entry.costCenter===centerFilter)&&(!query||(entry.description+' '+categoryLabel(entry.category)).toLowerCase().includes(query.toLowerCase()))&&(entryFilter==='all'||entryFilter==='settled'&&entry.status==='settled'||entryFilter==='receivable'&&entry.status==='open'&&entryDirection(entry.category)==='in'||entryFilter==='payable'&&entry.status==='open'&&entryDirection(entry.category)==='out')).sort((a,b)=>a.dueDate.localeCompare(b.dueDate))??[];
  const close=()=>setModal(null);
  const categoryOptions:Option[]=FINANCE_CATEGORIES.map(category=>({value:category.id,label:category.label}));
  const accountOptions:Option[]=state?.accounts.filter(account=>account.active).map(account=>({value:account.id,label:account.name}))??[];
  const peopleOptions:Option[]=members.map(member=>({value:member.id,label:member.name}));
  const propertyOptions:Option[]=properties.map(property=>({value:property.id,label:property.title}));
  const partnerOptions:Option[]=state?.partners.filter(partner=>partner.active).map(partner=>({value:partner.id,label:partner.name}))??[];
  const relationFields=(existing:{brokerId?:string|null;propertyId?:string|null;partnerId?:string|null;costCenter?:string}={}):Field[]=>[
    {key:'brokerId',label:'Corretor vinculado',type:'select',options:peopleOptions,required:false,value:String(existing.brokerId??'')},
    {key:'propertyId',label:'Imóvel vinculado',type:'select',options:propertyOptions,required:false,value:String(existing.propertyId??'')},
    {key:'partnerId',label:'Sócio vinculado',type:'select',options:partnerOptions,required:false,value:String(existing.partnerId??modal?.partnerId??''),showWhen:values=>partnerMovement(values.category),help:'Identifique o sócio em aportes, empréstimos de sócio, pró-labore ou distribuição. Uma venda pertence à empresa e segue a divisão entre todos.'},
    {key:'costCenter',label:'Centro de custo',required:false,value:String(existing.costCenter??''),help:'Ex.: Institucional, Captação, Vacaria.'},
  ];
  function exportEntries(){downloadCsv('eme-financeiro-'+month+'.csv',[
    ['Descrição','Categoria','Centro de custo','Valor (R$)','Competência','Vencimento','Baixa','Situação','Reconhecimento','Conta','Corretor','Imóvel'],
    ...entries.map(entry=>[entry.description,categoryLabel(entry.category),entry.costCenter,(entry.amountCents/100).toFixed(2).replace('.',','),entry.competenceDate,entry.dueDate,entry.settledDate,entryStatus(entry.status,entry.category),entry.recognition==='recognized'?'Realizado':'Previsão',accountName(entry.accountId),memberName(entry.brokerId),propertyName(entry.propertyId)]),
  ]);}
  function renderForm(){
    if(!modal||!state)return null;
    if(modal.kind==='account'){
      const existing=state.accounts.find(account=>account.id===modal.id);
      const fields:Field[]=[{key:'name',label:'Nome da conta',value:existing?.name,help:'Um nome fácil de reconhecer, como Conta principal ou Caixa físico.'},{key:'kind',label:'Tipo de conta',type:'select',value:existing?.kind??'bank',options:[{value:'bank',label:'Conta bancária'},{value:'cash',label:'Caixa físico'}]},{key:'bankName',label:'Banco / instituição',required:false,value:existing?.bankName},{key:'openingDate',label:'Data do saldo inicial',type:'date',value:existing?.openingDate??today()},{...moneyField('openingBalanceCents','Saldo total inicial',existing?.openingBalanceCents??0,'Pode ser negativo. Use o saldo conferido no extrato dessa data.'),min:undefined},moneyField('openingThirdPartyCents','Parcela pertencente a terceiros',existing?.openingThirdPartyCents??0,'Aluguéis e valores a repassar. Essa parcela não é receita da EME.')];
      return <FinanceModal key={modal.kind+':'+(modal.id??'')} title={existing?'Editar conta manual':'Adicionar conta manual'} description="Registre o saldo conferido no extrato na data de partida. Esse saldo compõe o caixa, mas não é receita nem lucro da DRE. Recebimentos e pagamentos posteriores serão registrados separadamente." onClose={close}><FinanceForm fields={fields} onClose={close} onReload={refresh} onSubmit={async values=>{const returnToSettlementId=modal.returnToSettlementId,returnToContribution=modal.returnToContribution;await command('account.save',{...values,id:existing?.id,openingBalanceCents:amount(values.openingBalanceCents),openingThirdPartyCents:amount(values.openingThirdPartyCents),active:existing?.active??true});if(returnToSettlementId)setModal({kind:'settle',id:returnToSettlementId});else if(returnToContribution)setModal({kind:'contribution',...returnToContribution});}}/></FinanceModal>;
    }
    if(modal.kind==='contribution'){
      const partner=state.partners.find(p=>p.id===modal.partnerId);if(!partner)return null;
      const category=modal.category==='loan_in'?'loan_in':'capital_in';
      const title=category==='loan_in'?'Lançar aporte reembolsável':'Lançar capital';
      if(!accountOptions.length)return <FinanceModal title={title} onClose={close}><Empty title="Cadastre a conta para acompanhar o aporte" description="Informe o saldo anterior ao novo aporte. O valor do aporte será registrado separadamente para evitar duplicação." action="Cadastrar conta e continuar" onAction={()=>setModal({kind:'account',returnToContribution:{category,partnerId:partner.id}})}/></FinanceModal>;
      return <FinanceModal key={'contribution:'+partner.id+category} title={title+' · '+partner.name} description={category==='loan_in'?'Dinheiro emprestado pelo sócio à empresa, com restituição prevista. Entra na compensação prioritária conforme as regras de caixa.':'Valor destinado ao capital social da empresa. Não gera dívida comum de restituição nem muda automaticamente as quotas cadastradas.'} onClose={close}><FinanceForm fields={[
        moneyField('amountCents','Valor do aporte'),
        {key:'settleNow',label:'O dinheiro já entrou na empresa?',type:'select',value:'',options:[{value:'yes',label:'Sim · registrar entrada no caixa agora'},{value:'no',label:'Ainda não · registrar aporte a receber'}],help:'Escolha explicitamente. Somente a entrada confirmada aumenta o saldo da conta.'},
        {key:'dueDate',label:'Data prevista do aporte',type:'date',value:today(),showWhen:v=>v.settleNow==='no'},
        {key:'settledDate',label:'Data do recebimento',type:'date',value:today(),max:today(),showWhen:v=>v.settleNow==='yes'},
        {key:'accountId',label:'Conta que recebeu o aporte',type:'select',options:accountOptions,value:accountOptions.length===1?accountOptions[0].value:'',showWhen:v=>v.settleNow==='yes'},
        {key:'notes',label:'Observações e referência do aporte',type:'textarea',required:false,full:true},
      ]} onClose={close} onReload={refresh} submitLabel="Registrar aporte" onSubmit={values=>{const received=values.settleNow==='yes';const date=received?values.settledDate:values.dueDate;return command('entry.save',{description:(category==='loan_in'?'Aporte reembolsável':'Capital social')+' · '+partner.name,category,partnerId:partner.id,amountCents:amount(values.amountCents),recognition:'recognized',competenceDate:date,dueDate:date,settleNow:received,accountId:received?values.accountId:undefined,settledDate:received?date:undefined,notes:values.notes},received?'Aporte recebido. Caixa e posição do sócio atualizados.':'Aporte registrado a receber. Ele aparece nos movimentos dos sócios; confirme o recebimento quando entrar.');}}><Notice>Se este dinheiro já faz parte do saldo inicial da conta, registre-o no histórico do sócio, em Editar sócio, para não duplicar o caixa.{partner.openingDate?' O histórico atual inclui movimentos até '+dateLabel(partner.openingDate)+'. Novas entradas precisam ter data posterior.':''}</Notice></FinanceForm></FinanceModal>;
    }
    if(modal.kind==='entry'){
      const existing=state.entries.find(entry=>entry.id===modal.id);
      const fields:Field[]=[
        {key:'description',label:'Descrição do lançamento',full:true,value:existing?.description},{key:'category',label:'Categoria',type:'select',options:categoryOptions,value:existing?.category??modal.category},moneyField('amountCents','Valor',existing?.amountCents),
        {key:'recognition',label:'Reconhecimento',type:'select',value:existing?.recognition??'recognized',options:[{value:'recognized',label:'Realizado · receita ganha ou obrigação incorrida'},{value:'forecast',label:'Previsão · apenas planejamento'}],help:'Receita e despesa realizadas compõem a DRE, mesmo ainda a receber ou pagar. Aportes, empréstimos e distribuições não são receita ou despesa.'},
        {key:'behavior',label:'Comportamento do custo',type:'select',value:existing?.behavior??'variable',options:[{value:'variable',label:'Variável / por operação'},{value:'fixed',label:'Fixo / recorrente'}]},{key:'competenceDate',label:'Data de competência',type:'date',value:existing?.competenceDate??today()},{key:'dueDate',label:'Data de vencimento',type:'date',value:existing?.dueDate??today()},
        ...(!existing?[{key:'repeat',label:'Repetir este lançamento?',type:'select' as const,value:'no',options:[{value:'no',label:'Não · lançamento único'},{value:'monthly',label:'Sim · todos os meses'}],full:true},{key:'endMonth',label:'Último mês da recorrência',type:'month' as const,showWhen:(v:FormValues)=>v.repeat==='monthly',help:'Inclui o primeiro e o último mês. Até 60 parcelas, criadas como previsão para conferência.'}]:[]),
        {key:'settleNow',label:'Movimentação no banco ou caixa',type:'select',value:'no',showWhen:v=>v.repeat!=='monthly'&&v.category!=='transfer',options:[{value:'no',label:'Ainda a receber ou pagar'},...(accountOptions.length?[{value:'yes',label:'Já recebi ou paguei · registrar agora'}]:[])],help:accountOptions.length?'Se já ocorreu, escolha a conta e a data para salvar e atualizar o caixa uma única vez.':'Salve o lançamento e use Receber ou Pagar para cadastrar a conta e confirmar a movimentação.'},
        {key:'accountId',label:'Conta da movimentação',type:'select',options:accountOptions,value:accountOptions.length===1?accountOptions[0].value:'',showWhen:v=>v.repeat!=='monthly'&&v.category!=='transfer'&&v.settleNow==='yes'},
        {key:'settledDate',label:'Data efetiva do recebimento ou pagamento',type:'date',value:today(),showWhen:v=>v.repeat!=='monthly'&&v.category!=='transfer'&&v.settleNow==='yes'},
        {...moneyField('withholdingCents','Imposto retido do sócio',0,'Informe a retenção apurada pela contabilidade. O valor bruto permanece na distribuição; o caixa paga ao sócio o bruto menos a retenção.'),showWhen:v=>v.repeat!=='monthly'&&v.category==='partner_distribution'&&v.settleNow==='yes'},
        {key:'withholdingDueDate',label:'Vencimento do imposto retido',type:'date',value:today(),showWhen:v=>v.repeat!=='monthly'&&v.category==='partner_distribution'&&v.settleNow==='yes'&&Number(v.withholdingCents)>0},
        ...relationFields(existing),{key:'notes',label:'Observações',type:'textarea',full:true,required:false,value:existing?.notes,help:'Anote comprovante, fornecedor, contrato ou contexto. Não inclua senhas bancárias.'},
      ];
      return <FinanceModal key={modal.kind+':'+(modal.id??'')} title={existing?'Editar lançamento':'Novo lançamento'} description="Registre a natureza do movimento e sua competência. Se o dinheiro já entrou ou saiu, confirme também a conta e a data. A receita de uma venda é da empresa; a divisão entre sócios segue as regras de distribuição." onClose={close}><FinanceForm fields={fields} onClose={close} onReload={refresh} onSubmit={values=>{
        const partnerId=partnerMovement(values.category)?values.partnerId:'';
        if(values.repeat==='monthly')return command('recurrence.save',{name:values.description,category:values.category,amountCents:amount(values.amountCents),startMonth:values.dueDate.slice(0,7),endMonth:values.endMonth,dueDay:Number(values.dueDate.slice(8)),competenceDay:Number(values.competenceDate.slice(8)),competenceOffset:(Number(values.competenceDate.slice(0,4))-Number(values.dueDate.slice(0,4)))*12+Number(values.competenceDate.slice(5,7))-Number(values.dueDate.slice(5,7)),behavior:values.behavior,brokerId:values.brokerId,propertyId:values.propertyId,partnerId,costCenter:values.costCenter,notes:values.notes,active:true,generateAll:true},'Recorrência e parcelas mensais criadas como previsão. Confira em Lançamentos e Recorrências.');
        const settleNow=values.category!=='transfer'&&values.settleNow==='yes';
        const withholdingCents=settleNow&&values.category==='partner_distribution'?amount(values.withholdingCents||'0'):0;
        return command('entry.save',{...values,partnerId,id:existing?.id,amountCents:amount(values.amountCents),settleNow,accountId:settleNow?values.accountId:undefined,settledDate:settleNow?values.settledDate:undefined,withholdingCents,withholdingDueDate:withholdingCents>0?values.withholdingDueDate:undefined},settleNow?'Lançamento e movimentação registrados juntos. O caixa foi atualizado.':'Lançamento salvo. Confirme Receber ou Pagar quando a movimentação ocorrer.');
      }}/></FinanceModal>;
    }
    if(modal.kind==='settle'){
      const existing=state.entries.find(entry=>entry.id===modal.id);if(!existing)return null;
      const direction=entryDirection(existing.category),transfer=direction==='transfer',retained=existing.category==='management_fee_retained';
      const title=retained?'Registrar retenção de honorários':transfer?'Registrar transferência entre contas':direction==='in'?'Registrar recebimento':'Registrar pagamento';
      const submitLabel=retained?'Confirmar retenção':transfer?'Confirmar transferência':direction==='in'?'Confirmar recebimento':'Confirmar pagamento';
      if(!accountOptions.length)return <FinanceModal key={modal.kind+':'+(modal.id??'')} title={title} description={existing.description+' · '+money(existing.amountCents)} onClose={close}><Empty title="Cadastre a conta desta movimentação" description="Informe a conta bancária ou o caixa físico usado. Depois do cadastro, você volta a este recebimento ou pagamento com o lançamento preservado." action="Cadastrar conta e continuar" onAction={()=>setModal({kind:'account',returnToSettlementId:existing.id})}/></FinanceModal>;
      return <FinanceModal key={modal.kind+':'+(modal.id??'')} title={title} description={existing.description+' · '+money(existing.amountCents)+(retained?'. A taxa será descontada dos valores de terceiros já registrados, sem criar um novo depósito.':'. Confirme uma movimentação que já ocorreu no banco ou no caixa. O portal registra o fato; não realiza a transferência bancária.')} onClose={close}><FinanceForm fields={[
        {key:'accountId',label:transfer?'Conta de origem':'Conta da movimentação',type:'select',options:accountOptions,value:existing.accountId??(accountOptions.length===1?accountOptions[0].value:'')},{key:'settledDate',label:transfer?'Data da transferência':direction==='in'?'Data do recebimento':'Data do pagamento',type:'date',value:today()},...(transfer?[{key:'destinationAccountId',label:'Conta de destino',type:'select' as const,options:accountOptions}]:[]),
        ...(existing.category==='partner_distribution'?[moneyField('withholdingCents','Imposto retido do sócio',0,'Informe o valor apurado pela contabilidade. O sócio recebe o bruto menos a retenção; o imposto vira uma conta a pagar separada.'),{key:'withholdingDueDate',label:'Vencimento do imposto retido',type:'date' as const,value:today(),showWhen:(values:FormValues)=>Number(values.withholdingCents)>0}]:[]),
      ]} onClose={close} onReload={refresh} submitLabel={submitLabel} onSubmit={values=>{const withholdingCents=existing.category==='partner_distribution'?amount(values.withholdingCents||'0'):0;return command('entry.settle',{id:existing.id,...values,withholdingCents,withholdingDueDate:withholdingCents>0?values.withholdingDueDate:undefined},(transfer?'Transferência':direction==='in'?'Recebimento':'Pagamento')+' registrado. O caixa foi atualizado.');}}><Notice>Registre cada movimentação uma única vez. Uma previsão passa a realizada ao confirmar o recebimento ou pagamento, preservando sua data de competência.{existing.category==='partner_distribution'?' A distribuição está em valor bruto; nenhuma alíquota é presumida.':''}</Notice></FinanceForm></FinanceModal>;
    }
    if(modal.kind==='cancel'||modal.kind==='cancel-adjustment'||modal.kind==='cancel-operation'){
      return <FinanceModal key={modal.kind+':'+(modal.id??'')} title="Cancelar registro" description={modal.kind==='cancel-operation'?'A operação e todos os seus lançamentos serão cancelados em conjunto, preservando o histórico. Se houve movimentação bancária real, confira também o estorno no banco.':'O registro continuará no histórico com a justificativa. Se houve movimentação bancária real, confira também o estorno no banco.'} onClose={close}><FinanceForm fields={[{key:'reason',label:'Motivo do cancelamento',type:'textarea',full:true}]} onClose={close} onReload={refresh} submitLabel="Confirmar cancelamento" onSubmit={values=>command(modal.kind==='cancel'?'entry.cancel':modal.kind==='cancel-operation'?'operation.cancel':'adjustment.cancel',{id:modal.id,reason:values.reason},'Cancelamento registrado no histórico.')}/></FinanceModal>;
    }
    if(modal.kind==='recurrence'){
      const existing=state.recurrences.find(recurrence=>recurrence.id===modal.id);
      const fields:Field[]=[{key:'name',label:'Descrição da recorrência',full:true,value:existing?.name},{key:'category',label:'Categoria',type:'select',options:categoryOptions.filter(option=>!['transfer','partner_distribution','capital_in','loan_in','investment'].includes(option.value)),value:existing?.category},moneyField('amountCents','Valor mensal',existing?.amountCents),{key:'behavior',label:'Comportamento',type:'select',value:existing?.behavior??'fixed',options:[{value:'fixed',label:'Fixo'},{value:'variable',label:'Variável'}]},{key:'dueDay',label:'Dia do vencimento',type:'number',min:'1',max:'31',step:'1',value:String(existing?.dueDay??10),help:'De 1 a 31. Meses mais curtos usam o último dia.'},{key:'startMonth',label:'Mês de início',type:'month',value:existing?.startMonth??month},{key:'endMonth',label:'Mês de término',type:'month',required:!existing,value:existing?.endMonth??''},...relationFields(existing)];
      return <FinanceModal key={modal.kind+':'+(modal.id??'')} title={existing?'Editar recorrência':'Nova recorrência mensal'} description="Cadastre honorários mensais da EME ou despesas recorrentes. Ao criar, todas as parcelas até o término ficam previstas. Edições alteram a regra; lançamentos já gerados permanecem preservados." onClose={close}><FinanceForm fields={fields} onClose={close} onReload={refresh} onSubmit={values=>command('recurrence.save',{...values,partnerId:partnerMovement(values.category)?values.partnerId:'',id:existing?.id,amountCents:amount(values.amountCents),dueDay:Number(values.dueDay),active:existing?.active??true,generateAll:!existing})}/></FinanceModal>;
    }
    if(modal.kind==='generate'){
      const existing=state.recurrences.find(recurrence=>recurrence.id===modal.id);if(!existing)return null;
      return <FinanceModal key={modal.kind+':'+(modal.id??'')} title="Gerar competência" description={existing.name+' · '+money(existing.amountCents)+' por mês. O lançamento ficará em aberto para conferência e baixa.'} onClose={close}><FinanceForm fields={[{key:'month',label:'Mês de competência',type:'month',value:month}]} onClose={close} onReload={refresh} submitLabel="Gerar lançamento" onSubmit={values=>command('recurrence.generate',{id:existing.id,month:values.month},'Competência gerada ou já existente; sem duplicar o lançamento.')}/></FinanceModal>;
    }
    if(modal.kind==='operation'){
      const fields:Field[]=[{key:'title',label:'Nome da operação',full:true},{key:'kind',label:'Tipo de operação',type:'select',value:'sale',options:[{value:'sale',label:'Venda'},{value:'rental',label:'Intermediação de locação'},{value:'management',label:'Administração · taxa cobrada separadamente'},{value:'other',label:'Outro serviço'}]},{key:'recognition',label:'Reconhecimento da operação',type:'select',value:'recognized',options:[{value:'recognized',label:'Realizada · receita já ganha, compõe a DRE'},{value:'forecast',label:'Previsão · negociação ainda não concluída'}],help:'Receita reconhecida pode estar a receber. O caixa só muda ao confirmar o recebimento.'},moneyField('amountCents','Receita da EME',undefined,'Somente a comissão / honorário da empresa. Não use o preço do imóvel nem o aluguel do proprietário.'),moneyField('taxCents','Tributos desta operação',0,'Informe o valor validado com a contabilidade. A comissão do corretor incide após este valor; confirme a tributação antes de distribuir lucros.'),percentageField('commissionBps','Participação do corretor após tributos',state.settings.defaultCommissionBps),moneyField('directCostCents','Outros custos diretos',0,'Custos desta operação ainda não lançados, sem incluir a comissão acima.'),percentageField('reserveBps','Reserva da empresa nesta operação',state.settings.reserveBps),{key:'brokerId',label:'Corretor responsável',type:'select',options:peopleOptions,required:false},{key:'propertyId',label:'Imóvel vinculado',type:'select',options:propertyOptions,required:false,help:propertyOptions.length?'Imóveis e captações cadastrados no portal.':'Nenhum imóvel foi carregado. Você pode salvar sem vínculo e conferir o cadastro.'},{key:'competenceDate',label:'Data de competência',type:'date',value:today()},{key:'dueDate',label:'Vencimento previsto',type:'date',value:today()},{key:'notes',label:'Observações da operação',type:'textarea',full:true,required:false}];
      return <FinanceModal key={modal.kind+':'+(modal.id??'')} title="Registrar operação" description="A venda concluída entra como receita reconhecida, com comissão e custos vinculados. Escolha Previsão apenas para uma negociação ainda não concluída. O resultado da empresa é distribuído entre todos os sócios conforme as regras; não se vincula a venda a um sócio específico." onClose={close}><FinanceForm fields={fields} onClose={close} onReload={refresh} submitLabel="Criar operação" onSubmit={values=>command('operation.create',{...values,amountCents:amount(values.amountCents),taxCents:amount(values.taxCents),commissionBps:amount(values.commissionBps),directCostCents:amount(values.directCostCents),reserveBps:amount(values.reserveBps)},'Operação criada com receita e custos vinculados. Registre o recebimento em Lançamentos quando o valor entrar.')}><Notice>Os valores vinculados são criados uma única vez. A reserva e a distribuição entre sócios são destinações do resultado e não geram despesas ou transferências bancárias automáticas.</Notice></FinanceForm></FinanceModal>;
    }
    if(modal.kind==='partner'){
      const existing=state.partners.find(partner=>partner.id===modal.id);
      return <FinanceModal key={modal.kind+':'+(modal.id??'')} title={existing?'Editar sócio':'Adicionar sócio'} description="Informe a quota e, se necessário, o histórico de aportes já incluído no saldo inicial das contas. Esse histórico organiza a posição de cada sócio e não cria nova entrada de caixa. Aportes novos devem ser lançados individualmente." onClose={close}><FinanceForm fields={[
        {key:'name',label:'Nome do sócio',value:existing?.name},percentageField('shareBps','Participação na distribuição',existing?.shareBps),
        {key:'openingDate',label:'Data de referência do histórico',type:'date',required:false,value:existing?.openingDate??'',help:'Obrigatória quando houver valores históricos. Use uma data anterior aos novos movimentos.'},
        moneyField('openingCapitalCents','Capital já aportado no histórico',existing?.openingCapitalCents??0,'Capital social não reembolsável pelo plano automático.'),moneyField('openingLoanCents','Aportes reembolsáveis no histórico',existing?.openingLoanCents??0,'Valores emprestados pelo sócio à empresa, com restituição prevista.'),moneyField('openingRepaidCents','Valor já restituído no histórico',existing?.openingRepaidCents??0,'Somente restituição de principal dos aportes reembolsáveis.'),
      ]} onClose={close} onReload={refresh} onSubmit={values=>command('partner.save',{id:existing?.id,name:values.name,shareBps:amount(values.shareBps),active:existing?.active??true,openingDate:values.openingDate||null,openingCapitalCents:amount(values.openingCapitalCents),openingLoanCents:amount(values.openingLoanCents),openingRepaidCents:amount(values.openingRepaidCents)})}/></FinanceModal>;
    }
    if(modal.kind==='settings'){
      return <FinanceModal key={modal.kind+':'+(modal.id??'')} title="Regras e metas da empresa" description="A reserva padrão também protege receitas avulsas recebidas. Operações preservam o percentual informado na criação. A proteção usa o maior valor entre a reserva acumulada e a meta mínima, sem somar duas vezes. O plano prioriza compensar aportes reembolsáveis em excesso à proporção dos sócios; a distribuição de lucros aguarda esse equilíbrio." onClose={close}><FinanceForm fields={[{...percentageField('reserveBps','Reserva padrão por operação',state.settings.reserveBps),required:false},{...percentageField('defaultCommissionBps','Comissão padrão do corretor',state.settings.defaultCommissionBps),required:false},{...moneyField('cashTargetCents','Meta de caixa próprio',state.settings.cashTargetCents,'Defina uma meta para habilitar a programação protegida. Zero é uma escolha explícita.'),required:false},{...moneyField('initialInvestmentCents','Investimento inicial para payback',state.settings.initialInvestmentCents),required:false},{...percentageField('partnerRepaymentBps','Limite mensal do caixa livre para compensação',state.settings.partnerRepaymentBps??2500),help:'Sugestão inicial de 25%. O limite é mensal e não se renova a cada clique.'}]} onClose={close} onReload={refresh} onSubmit={values=>command('settings.save',{...Object.fromEntries(Object.entries(values).map(([key,value])=>[key,value===''?null:amount(value)])),repaymentPolicy:'excess_first'})}/></FinanceModal>;
    }
    if((modal.kind==='distribution-plan'||modal.kind==='repayment-plan')&&report){
      const repayment=modal.kind==='repayment-plan',available=repayment?report.partnerCapital.plannedCents:report.distribution.eligibleCents;
      return <FinanceModal key={modal.kind+':'+(modal.id??'')} title={repayment?'Programar compensação de aportes':'Programar distribuição de lucros'} description={(repayment?'O rateio será calculado para os sócios com excesso reembolsável, respeitando o limite mensal e a proteção de caixa.':'O valor será distribuído entre todos os sócios ativos pelas quotas cadastradas. Valores brutos; retenções são informadas na confirmação do pagamento.')+' Serão criadas contas a pagar, sem pagamento bancário automático.'} onClose={close}><FinanceForm fields={[moneyField('amountCents','Total a programar',available,'Máximo disponível agora: '+money(available)+'. O valor será conferido novamente ao confirmar.'),{key:'dueDate',label:'Vencimento das parcelas dos sócios',type:'date',value:today()},{key:'reason',label:'Deliberação e motivo da programação',type:'textarea',full:true,help:'Identifique a aprovação dos sócios e a referência da deliberação.'}]} onClose={close} onReload={refresh} submitLabel={repayment?'Confirmar compensação programada':'Confirmar distribuição programada'} onSubmit={values=>command(repayment?'repayment.plan':'distribution.plan',{from,to,amountCents:amount(values.amountCents),dueDate:values.dueDate,reason:values.reason},'Plano registrado para todos os sócios contemplados. Confira as parcelas em Lançamentos e confirme os pagamentos quando ocorrerem.')}><Notice>Competência: {monthLabel(month)}. Nenhuma despesa de DRE é criada pela destinação do lucro ou pela restituição de principal. Os pagamentos efetivos continuam sendo registrados separadamente.</Notice></FinanceForm></FinanceModal>;
    }
    if(modal.kind==='adjustment'){
      return <FinanceModal key={modal.kind+':'+(modal.id??'')} title="Ajuste gerencial da DRE" description="Use para ajustes de competência documentados. Não substitui um lançamento financeiro e não altera o caixa. Valores positivos aumentam o grupo escolhido; negativos reduzem." onClose={close}><FinanceForm fields={[{key:'label',label:'Descrição do ajuste',full:true},{key:'group',label:'Grupo da DRE',type:'select',options:DRE_GROUPS.map(group=>({value:group.id,label:group.label}))},{...moneyField('amountCents','Valor do ajuste'),min:undefined},{key:'competenceDate',label:'Data de competência',type:'date',value:today()},{key:'reason',label:'Justificativa e referência',type:'textarea',full:true}]} onClose={close} onReload={refresh} onSubmit={values=>command('adjustment.save',{...values,amountCents:amount(values.amountCents)},'Ajuste gerencial salvo separadamente dos lançamentos.')}/></FinanceModal>;
    }
    return null;
  }
  if(user.role!=='admin')return <Notice>O financeiro da empresa é restrito aos administradores.</Notice>;
  if(loading&&!snapshot)return <div className="pf-loading" role="status">Carregando o financeiro da EME…<div className="pf-skeleton"/></div>;
  if(!state||!report)return <div className="pf-workspace"><p className="pt-error" role="alert">{error||'Não foi possível carregar os dados.'}</p><button className="ps-button" onClick={refresh}>Tentar novamente<RefreshCw size={16}/></button></div>;
  return <section className="pf-workspace" aria-label="Central financeira"><div className="pf-toolbar"><div><span className="ps-overline">CONTROLE, RESULTADO E PRÓXIMOS PASSOS</span><p>As finanças da EME em um só lugar. Valores de proprietários permanecem separados da receita e do caixa próprio.</p></div><label className="pf-period">Competência selecionada<input type="month" min="1900-01" max="2200-12" value={month} onChange={event=>{const value=event.target.value;if(/^\d{4}-(0[1-9]|1[0-2])$/.test(value)&&value>='1900-01'&&value<='2200-12')setMonth(value);}}/></label></div><nav className="pf-tabs" aria-label="Áreas do financeiro">{financeGroups.map(g=><button key={g.name} aria-current={g.ids.includes(tab)?'page':undefined} onClick={()=>setTab(g.ids[0] as typeof tab)}>{g.name}</button>)}</nav><nav className="pf-tabs pa-finance-subtabs" aria-label="Seções do financeiro">{tabs.filter(([id])=>financeGroups.find(g=>g.ids.includes(tab))?.ids.includes(id)).map(([id,label])=><button key={id} aria-current={tab===id?'page':undefined} onClick={()=>setTab(id)}>{label}</button>)}</nav>{error&&<p className="pt-error" role="alert">{error}</p>}
  <div hidden={tab!=='simulation'}><CommissionSimulator key={user.id}/></div>
  {tab==='agreements'&&<BrokerCommissions user={user} managementOnly/>}
  {tab==='overview'&&<>
    <div className="pf-hero"><div><span className="ps-overline">CAIXA PRÓPRIO · SALDO ATUAL</span><h2>{money(report.cash.availableCents)}</h2><p>Saldo da empresa após separar os valores de terceiros. Inclui saldos iniciais, aportes e movimentações até hoje; não é o lucro da DRE nem o valor liberado para distribuição.</p></div><div className="pf-hero-side"><div className="pf-hero-row"><span>Saldo total das contas</span><strong>{money(report.cash.balanceCents)}</strong></div><div className="pf-hero-row"><span>Valores de terceiros a repassar</span><strong>{money(report.cash.thirdPartyHeldCents)}</strong></div><div className="pf-hero-row"><span>Reserva sugerida acumulada</span><strong>{money(report.cash.reserveSuggestedCents)}</strong></div><div className="pf-hero-row"><span>Meta de caixa próprio</span><strong>{report.cash.targetCents==null?'Ainda não definida':money(report.cash.targetCents)}</strong></div></div></div>
    <div className="pf-grid"><Metric label={'Receita EME · '+monthLabel(month)} value={money(report.dre.combined.revenueCents)} note="Regime de competência · realizada"/><Metric label="Lucro bruto" value={money(report.dre.combined.grossProfitCents)} note="Após deduções, comissões e custos diretos" negative={report.dre.combined.grossProfitCents<0}/><Metric label="Lucro líquido gerencial" value={money(report.dre.combined.netProfitCents)} note="Inclui despesas, financeiro e tributos lançados" negative={report.dre.combined.netProfitCents<0}/><Metric label="MRR · recorrência ativa hoje" value={money(report.mrrCents)} note={'ARR anualizado: '+money(report.arrCents)}/></div>
    {!state.accounts.length&&<Empty title="Comece pelo saldo real da empresa." description="Cadastre suas contas com o saldo conferido no extrato. Depois, organize despesas, receitas e compromissos para acompanhar a evolução do caixa." action="Adicionar primeira conta" onAction={()=>setModal({kind:'account'})}/>}
    {report.warnings.length>0&&<details className="pf-warning-list"><summary>{report.warnings.length} pontos para conferir no financeiro</summary><ul>{report.warnings.map((warning,index)=><li key={index}>{warning}</li>)}</ul></details>}
    <div className="pf-split"><section className="pf-panel"><div className="pf-heading"><div><h3>O mês em movimento</h3><p>Recebimentos e pagamentos registrados em {monthLabel(month)}.</p></div><button className="ps-text-button" onClick={()=>setTab('entries')}>Ver lançamentos<ArrowRight size={14}/></button></div><div className="pf-list"><div className="pf-list-row"><span className="pf-inline"><ArrowDownLeft size={16}/>Recebimentos</span><strong>{money(report.period.receivedCents)}</strong></div><div className="pf-list-row"><span className="pf-inline"><ArrowUpRight size={16}/>Pagamentos</span><strong>{money(report.period.paidCents)}</strong></div><div className="pf-list-row"><span>Custos fixos da competência</span><strong>{money(report.period.fixedCostsCents)}</strong></div><div className="pf-list-row"><span>Custos variáveis da competência</span><strong>{money(report.period.variableCostsCents)}</strong></div><div className="pf-list-row"><span>A receber em atraso<small>Compromissos em aberto até hoje</small></span><strong>{money(report.period.overdueReceivableCents)}</strong></div><div className="pf-list-row"><span>A pagar em atraso</span><strong className={report.period.overduePayableCents?'pf-negative':undefined}>{money(report.period.overduePayableCents)}</strong></div></div><div className="pf-actions" style={{marginTop:20}}><button className="ps-button ps-button--primary" onClick={()=>setModal({kind:'entry'})}><Plus size={15}/>Lançar movimento</button><button className="ps-button" onClick={()=>setModal({kind:'operation'})}>Registrar operação</button></div></section><section className="pf-panel"><div className="pf-heading"><div><h3>Fôlego para crescer</h3><p>Metas e recuperação do investimento.</p></div><button className="ps-text-button" onClick={()=>setModal({kind:'settings'})}>Definir metas<ArrowRight size={14}/></button></div><div className="pf-list"><div className="pf-list-row"><span>Meta de caixa</span><strong>{report.cash.targetCents==null?'A definir':money(report.cash.targetCents)}</strong></div>{report.cash.targetCents!=null&&report.cash.targetCents>0&&<div><div className="pf-health-bar" role="meter" aria-label="Progresso da meta de caixa" aria-valuemin={0} aria-valuemax={100} aria-valuenow={Math.max(0,Math.min(100,Math.round(report.cash.availableCents/report.cash.targetCents*100)))}><span style={{width:Math.max(0,Math.min(100,report.cash.availableCents/report.cash.targetCents*100))+'%'}}/></div><small className="pf-muted">{report.cash.gapCents&&report.cash.gapCents>0?money(report.cash.gapCents)+' para atingir a meta':'Meta atingida no saldo atual'}</small></div>}<div className="pf-list-row"><span>Investimento inicial</span><strong>{report.payback.investmentCents==null?'A definir':money(report.payback.investmentCents)}</strong></div><div className="pf-list-row"><span>Caixa operacional acumulado<small>Base gerencial da recuperação</small></span><strong className={report.payback.recoveredCents<0?'pf-negative':undefined}>{money(report.payback.recoveredCents)}</strong></div><div className="pf-list-row"><span>Prazo estimado restante</span><strong>{report.payback.reached?'Investimento recuperado':report.payback.monthsEstimate==null?'Sem base positiva':report.payback.monthsEstimate.toLocaleString('pt-BR',{maximumFractionDigits:1})+' meses'}</strong></div></div><p className="pf-note-line">Prazo para recuperar o investimento restante, pela média do caixa operacional dos meses completos. O mês em andamento fica fora da média. A estimativa não é garantia de retorno.</p></section></div>
    <section className="pf-panel"><div className="pf-heading"><div><h3>Onde estamos investindo</h3><p>Despesas por categoria na competência selecionada.</p></div><button className="ps-text-button" onClick={()=>setTab('reports')}>DRE e projeções<ArrowRight size={14}/></button></div>{report.period.byCategory.filter(item=>item.direction==='out'&&FINANCE_CATEGORIES.find(category=>category.id===item.category)?.dreGroup!=null).length?<div className="pf-list">{report.period.byCategory.filter(item=>item.direction==='out'&&FINANCE_CATEGORIES.find(category=>category.id===item.category)?.dreGroup!=null).sort((a,b)=>b.amountCents-a.amountCents).map(item=><div className="pf-list-row" key={item.category}><span>{item.label}</span><strong>{money(item.amountCents)}</strong></div>)}</div>:<p className="pf-muted">As despesas aparecerão aqui conforme forem registradas.</p>}</section>
  </>}
  {tab==='accounts'&&<><div className="pf-heading"><div><h2>Contas e caixa da empresa</h2><p>Controle manual com histórico de cada recebimento e pagamento.</p></div><button className="ps-button ps-button--primary" onClick={()=>setModal({kind:'account'})}><Plus size={16}/>Adicionar conta</button></div><Notice>Saldo inicial é a posição do caixa na data informada: não é receita nem lucro e não deve ser lançado novamente como venda. Confira os saldos com seus extratos. Esta tela registra movimentações; não acessa nem movimenta contas bancárias.</Notice>{!state.accounts.length?<Empty title="Suas contas, organizadas" description="Cadastre uma conta bancária ou o caixa físico da EME e informe o saldo inicial conferido." action="Cadastrar primeira conta" onAction={()=>setModal({kind:'account'})}/>:<div className="pf-account-grid">{state.accounts.map(account=><article className="pf-account" key={account.id}>{account.kind==='cash'?<Banknote size={24}/>:<Landmark size={24}/>}<h3>{account.name}</h3><p>{account.kind==='cash'?'Caixa físico':account.bankName||'Conta bancária manual'}{!account.active?' · Inativa':''}</p><strong className={(report.cash.accounts.find(item=>item.id===account.id)?.balanceCents??0)<0?'pf-negative':undefined}>{money(report.cash.accounts.find(item=>item.id===account.id)?.balanceCents??0)}</strong><small>Saldo inicial {money(account.openingBalanceCents)} em {dateLabel(account.openingDate)}</small><small>Terceiros no saldo inicial: {money(account.openingThirdPartyCents)}</small><button className="ps-text-button" style={{marginTop:18}} onClick={()=>setModal({kind:'account',id:account.id})}>Conferir dados<ArrowUpRight size={14}/></button></article>)}</div>}</>}
  {tab==='operations'&&<><section className="pf-panel"><div className="pf-heading"><div><h2>Cada operação, seu resultado.</h2><p>Operação é um negócio que gera honorários para a EME, como uma venda intermediada. A captação cadastra o imóvel; ainda não gera receita. Gastos de captação entram em Lançamentos.</p></div><button className="ps-button ps-button--primary" onClick={()=>setModal({kind:'operation'})}><Plus size={16}/>Nova operação</button></div>{!state.operations.filter(operation=>operation.competenceDate.slice(0,7)===month).length?<Empty title="Nenhuma operação nesta competência" description="Registre a comissão ou honorário da EME para criar os lançamentos vinculados e acompanhar a contribuição por corretor." action="Registrar operação" onAction={()=>setModal({kind:'operation'})}/>:<div className="pf-table-wrap"><table className="pf-table"><thead><tr><th>Operação</th><th>Corretor</th><th className="pf-number">Receita EME</th><th className="pf-number">Tributos</th><th className="pf-number">Base do corretor</th><th className="pf-number">Comissão</th><th className="pf-number">Custo direto</th><th className="pf-number">Reserva</th><th>Ações</th></tr></thead><tbody>{state.operations.filter(operation=>operation.competenceDate.slice(0,7)===month).map(operation=><tr key={operation.id}><td><strong>{operation.title}</strong>{operation.status==='cancelled'&&<small>Cancelada</small>}<small>{propertyName(operation.propertyId)}</small><small>{dateLabel(operation.competenceDate)} · {state.entries.find(entry=>entry.operationId===operation.id&&entryDirection(entry.category)==='in')?.recognition==='forecast'?'Previsão':'Receita reconhecida'}</small></td><td>{memberName(operation.brokerId)}</td><td className="pf-number">{money(operation.amountCents)}</td><td className="pf-number">{money(operation.taxCents??0)}</td><td className="pf-number">{money(Math.max(0,operation.amountCents-(operation.taxCents??0)))}</td><td className="pf-number">{money(operation.commissionCents)}<small>{percent(operation.commissionBps/100)}</small></td><td className="pf-number">{money(operation.directCostCents)}</td><td className="pf-number">{money(operation.reserveCents)}<small>{percent(operation.reserveBps/100)}</small></td><td><div className="pf-actions"><button className="ps-text-button" onClick={()=>{setTab('entries');setQuery(operation.title);setEntryFilter('all');setCategoryFilter('');setCenterFilter('');}}>Ver recebimento e custos</button>{operation.status!=='cancelled'&&<button className="ps-text-button" onClick={()=>setModal({kind:'cancel-operation',id:operation.id})}>Cancelar operação</button>}</div></td></tr>)}</tbody></table></div>}<p className="pf-note-line">Receita EME é a remuneração da empresa. A comissão do corretor é calculada após os tributos informados. Confirme a tributação com a contabilidade antes de distribuir lucros. A reserva sugerida acumulada é calculada sobre receitas de operações já recebidas. É uma referência de retenção, não um saldo bancário segregado nem uma despesa da DRE.</p></section><section className="pf-panel" style={{marginTop:20}}><div className="pf-heading"><div><h3>Resultado por corretor</h3><p>Contribuição antes das despesas gerais da empresa.</p></div></div>{!report.brokers.length?<p className="pf-muted">Vincule um corretor à operação ou ao lançamento para acompanhar seu resultado.</p>:<div className="pf-table-wrap"><table className="pf-table"><thead><tr><th>Corretor</th><th>Operações</th><th className="pf-number">Receita</th><th className="pf-number">Comissão</th><th className="pf-number">Custos diretos</th><th className="pf-number">Contribuição</th><th className="pf-number">Recebido</th></tr></thead><tbody>{report.brokers.map(broker=><tr key={broker.id}><td><span className="pf-broker-name"><i>{broker.name.slice(0,1)}</i>{broker.name}</span></td><td>{broker.operations}</td><td className="pf-number">{money(broker.revenueCents)}</td><td className="pf-number">{money(broker.commissionCents)}</td><td className="pf-number">{money(broker.directCostCents)}</td><td className="pf-number"><strong className={broker.contributionCents<0?'pf-negative':undefined}>{money(broker.contributionCents)}</strong></td><td className="pf-number">{money(broker.receivedCents)}</td></tr>)}</tbody></table></div>}</section></>}
  {tab==='partners'&&<>
    <section className="pf-panel"><div className="pf-heading"><div><h2>Sócios, aportes e regras de distribuição.</h2><p>A empresa reconhece a receita das vendas; o resultado é destinado a todos conforme as quotas e a proteção de caixa.</p></div><button className="ps-button" onClick={()=>setModal({kind:'settings'})}>Configurar regras<ArrowUpRight size={15}/></button></div><dl className="pf-setting-summary"><div><dt>Reserva padrão por operação</dt><dd>{state.settings.reserveBps==null?'A definir':percent(state.settings.reserveBps/100)}</dd></div><div><dt>Comissão padrão após tributos</dt><dd>{state.settings.defaultCommissionBps==null?'A definir':percent(state.settings.defaultCommissionBps/100)}</dd></div><div><dt>Meta de caixa próprio</dt><dd>{state.settings.cashTargetCents==null?'A definir':money(state.settings.cashTargetCents)}</dd></div></dl><Notice>Pró-labore é despesa operacional. Distribuição de lucros e restituição de principal são saídas de caixa fora da DRE. O histórico de aporte cadastrado no sócio já deve estar refletido nas contas, para não duplicar o dinheiro.</Notice></section>
    <section className="pf-panel pf-partner-list"><div className="pf-heading"><h3>Quadro de sócios</h3><button className="ps-button" onClick={()=>setModal({kind:'partner'})}><Plus size={15}/>Adicionar sócio</button></div>{!state.partners.length?<p className="pf-muted">Cadastre os sócios e suas quotas. Nenhuma participação é presumida.</p>:<div className="pf-list">{state.partners.map(partner=><div className="pf-list-row" key={partner.id}><span><strong>{partner.name}</strong><small>{partner.active?'Participação ativa':'Inativo'} · {percent(partner.shareBps/100)}</small>{partner.openingDate&&<small>Histórico de abertura em {dateLabel(partner.openingDate)}</small>}</span><div className="pf-actions"><button className="ps-text-button" onClick={()=>setModal({kind:'partner',id:partner.id})}>Editar sócio</button>{partner.active&&<><button className="ps-button" onClick={()=>setModal({kind:'contribution',category:'capital_in',partnerId:partner.id})}>Lançar capital</button><button className="ps-button" onClick={()=>setModal({kind:'contribution',category:'loan_in',partnerId:partner.id})}>Lançar aporte reembolsável</button></>}</div></div>)}</div>}<p className="pf-note-line">Quotas ativas: {percent(report.distribution.allocatedBps/100)}. A soma deve ser 100% para distribuir o resultado.</p></section>
    <section className="pf-panel" aria-label="Movimentos de aportes"><div className="pf-heading"><div><h3>Movimentos de aportes · todas as datas</h3><p>Capital social compõe o patrimônio; aporte reembolsável compõe a dívida com o sócio. Nenhum dos dois é lucro.</p></div></div><div className="pf-table-wrap"><table className="pf-table"><thead><tr><th>Sócio e aporte</th><th>Data</th><th>Situação</th><th className="pf-number">Valor</th><th>Ações</th></tr></thead><tbody>{state.entries.filter(e=>['capital_in','loan_in'].includes(e.category)).slice().sort((a,b)=>b.createdAt.localeCompare(a.createdAt)).map(e=><tr key={e.id}><td><strong>{state.partners.find(p=>p.id===e.partnerId)?.name??'Sem sócio identificado'}</strong><small>{categoryLabel(e.category)}</small><small>{e.description}</small></td><td>{dateLabel(e.settledDate||e.dueDate)}{e.accountId&&<small>{accountName(e.accountId)}</small>}</td><td>{entryStatus(e.status,e.category)}</td><td className="pf-number">{money(e.amountCents)}</td><td><div className="pf-actions">{e.status==='open'&&<><button className="ps-button" onClick={()=>setModal({kind:'settle',id:e.id})}>Receber aporte</button><button className="ps-text-button" onClick={()=>setModal({kind:'entry',id:e.id})}>Editar</button></>}{e.status!=='cancelled'&&<button className="ps-text-button" onClick={()=>setModal({kind:'cancel',id:e.id})}>Cancelar aporte</button>}</div></td></tr>)}</tbody></table></div>{!state.entries.some(e=>['capital_in','loan_in'].includes(e.category))&&<p className="pf-muted">Nenhum movimento de aporte. Valores históricos aparecem no quadro abaixo.</p>}</section>
    <PartnerCapitalPanel report={report} onPlan={()=>setModal({kind:'repayment-plan'})} onRules={()=>setModal({kind:'settings'})}/>
    <ProfitDistribution report={report} periodLabel={monthLabel(month)} onPlan={()=>setModal({kind:'distribution-plan'})} onRules={()=>setModal({kind:'settings'})}/>
  </>}
  {tab==='reports'&&<><section className="pf-panel"><div className="pf-heading"><div><h2>DRE gerencial</h2><p>Competência de {monthLabel(month)} · valores realizados e ajustes separados.</p></div><div className="pf-actions"><button className="ps-button" onClick={()=>downloadCsv('eme-dre-'+month+'.csv',[['Linha','Automático (R$)','Ajustes (R$)','Combinado (R$)'],...dreRows.map(row=>[row.label,...(['automatic','manual','combined'] as const).map(mode=>(report.dre[mode][row.key]/100).toFixed(2).replace('.',','))])])}><Download size={15}/>Exportar DRE</button><button className="ps-button ps-button--primary" onClick={()=>setModal({kind:'adjustment'})}><Plus size={15}/>Ajuste manual</button></div></div><div className="pf-table-wrap"><table className="pf-table"><thead><tr><th>Demonstração</th><th className="pf-number">Automático</th><th className="pf-number">Ajustes manuais</th><th className="pf-number">Combinado</th></tr></thead><tbody>{dreRows.map(row=><tr key={row.key} className={row.total?'pf-dre-row--total':undefined}><td>{row.label}</td><td className="pf-number">{money(report.dre.automatic[row.key])}</td><td className="pf-number">{money(report.dre.manual[row.key])}</td><td className="pf-number"><strong className={report.dre.combined[row.key]<0?'pf-negative':undefined}>{money(report.dre.combined[row.key])}</strong></td></tr>)}</tbody></table></div><div className="pf-grid" style={{marginBottom:0}}><Metric label="Margem bruta" value={percent(report.dre.combined.netRevenueCents>0?report.dre.combined.grossProfitCents/report.dre.combined.netRevenueCents*100:null)} note="Lucro bruto / receita líquida"/><Metric label="Margem líquida" value={percent(report.dre.combined.netRevenueCents>0?report.dre.combined.netProfitCents/report.dre.combined.netRevenueCents*100:null)} note="Lucro líquido / receita líquida"/><Metric label="MRR" value={money(report.mrrCents)} note="Receita mensal recorrente ativa hoje"/><Metric label="ARR" value={money(report.arrCents)} note="MRR × 12 · anualização, não caixa recebido"/></div><p className="pf-note-line">DRE gerencial baseada nos registros do portal. Revise classificação e tributos com a contabilidade. Aportes, transferências, empréstimos, repasses e distribuição de lucros ficam fora da receita e das despesas operacionais.</p></section>
    <ProfitDistribution report={report} periodLabel={monthLabel(month)} onPlan={()=>setModal({kind:'distribution-plan'})} onRules={()=>setTab('partners')}/>
    <section className="pf-panel" style={{marginTop:20}}><div className="pf-heading"><div><h3>Próximos seis meses</h3><p>Projeção pelos vencimentos em aberto e recorrências, sem duplicar competências já geradas.</p></div></div><div className="pf-projection" aria-label="Caixa próprio projetado">{report.projections.map(item=><div className="pf-projection-month" key={item.month}><span className={item.availableCents<0?'pf-negative':undefined}>{money(item.availableCents)}</span><i className={item.availableCents<0?'pf-bar-negative':undefined} style={{height:Math.max(3,Math.abs(item.availableCents)/Math.max(1,...report.projections.map(value=>Math.abs(value.availableCents)))*100)+'px'}}/><small>{monthLabel(item.month)}</small></div>)}</div><div className="pf-table-wrap" style={{marginTop:20}}><table className="pf-table"><thead><tr><th>Mês</th><th className="pf-number">Saldo inicial</th><th className="pf-number">Entradas totais</th><th className="pf-number">Saídas totais</th><th className="pf-number">Terceiros incluídos · entrada</th><th className="pf-number">Terceiros incluídos · saída</th><th className="pf-number">Caixa próprio</th></tr></thead><tbody>{report.projections.map(item=><tr key={item.month}><td>{monthLabel(item.month)}{item.belowTarget&&<small>Abaixo da meta</small>}</td><td className="pf-number">{money(item.openingCents)}</td><td className="pf-number">{money(item.receivableCents)}</td><td className="pf-number">{money(item.payableCents)}</td><td className="pf-number">{money(item.thirdPartyInCents)}</td><td className="pf-number">{money(item.thirdPartyOutCents)}{item.retainedFeesCents>0&&<small>Taxas retidas: {money(item.retainedFeesCents)}</small>}</td><td className="pf-number"><strong className={item.availableCents<0?'pf-negative':undefined}>{money(item.availableCents)}</strong></td></tr>)}</tbody></table></div><p className="pf-note-line">As parcelas de terceiros já estão incluídas nas entradas e saídas totais. Taxas retidas reduzem o valor a repassar, sem um novo depósito. A projeção mostra os compromissos registrados, não prevê novas vendas. Atualize os vencimentos conforme as negociações evoluírem.</p></section>
    <div className="pf-split"><section className="pf-panel"><div className="pf-heading"><h3>Ajustes manuais da competência</h3></div>{!state.adjustments.filter(adjustment=>adjustment.competenceDate.slice(0,7)===month).length?<p className="pf-muted">Nenhum ajuste manual. O resultado vem integralmente dos lançamentos.</p>:<div className="pf-list">{state.adjustments.filter(adjustment=>adjustment.competenceDate.slice(0,7)===month).map(adjustment=><div className="pf-list-row" key={adjustment.id}><span><strong>{adjustment.label}</strong><small>{DRE_GROUPS.find(group=>group.id===adjustment.group)?.label} · {adjustment.status==='cancelled'?'Cancelado':dateLabel(adjustment.competenceDate)}</small><small>{adjustment.reason}</small></span><strong>{money(adjustment.amountCents)}</strong>{adjustment.status==='active'&&<button className="ps-text-button" onClick={()=>setModal({kind:'cancel-adjustment',id:adjustment.id})}>Cancelar</button>}</div>)}</div>}</section><section className="pf-panel"><div className="pf-heading"><h3>Histórico do financeiro</h3></div>{!snapshot?.history?.length?<p className="pf-muted">As alterações financeiras serão registradas aqui.</p>:<ol className="pf-history">{snapshot.history.slice(0,30).map(item=><li key={item.id}><strong>{actionLabel(item.action)}</strong>{item.detail&&<div>{item.detail}</div>}<small>{item.author||'Administrador'} · {new Date(item.created_at??item.createdAt??'').toLocaleString('pt-BR')}</small></li>)}</ol>}</section></div>
  </>}
  <div hidden={!(['partners'] as string[]).includes(tab)}><OwnerPaymentPlan key={user.id} state={state} report={report} asOf={today()} onSave={plan=>command('settings.save',{ownerPlan:plan},'Planejamento dos sócios salvo. Nenhum pagamento ou lançamento real foi criado.')} onPay={id=>setModal({kind:'settle',id})}/></div>
  {(['reports'] as string[]).includes(tab)&&<FinanceOutlook state={state} asOf={today()} onRules={()=>setModal({kind:'settings'})}/> }
  {tab==='entries'&&<section className="pf-panel">
    <div className="pf-heading"><div><h2>Receber, pagar e conferir o caixa.</h2><p>Competência de {monthLabel(month)}. O resultado é reconhecido pela competência; o caixa muda no recebimento ou pagamento.</p></div><div className="pf-actions"><button className="ps-button" onClick={exportEntries} disabled={!entries.length}><Download size={15}/>Exportar CSV</button><button className="ps-button ps-button--primary" onClick={()=>setModal({kind:'entry'})}><Plus size={15}/>Novo lançamento</button></div></div>
    <div className="pf-entry-tabs" aria-label="Filtrar movimentos">{([['all','Todos'],['receivable','A receber'],['payable','A pagar'],['settled','Recebidos e pagos']] as const).map(([value,label])=><button key={value} type="button" className="ps-button" aria-pressed={entryFilter===value} onClick={()=>setEntryFilter(value)}>{label}</button>)}</div>
    <div className="pf-filters"><label>Período dos lançamentos<select value={entryScope} onChange={event=>setEntryScope(event.target.value)}><option value="month">Competência selecionada</option><option value="all">Todas as datas</option></select></label><label>Buscar lançamento<input value={query} onChange={event=>setQuery(event.target.value)} placeholder="Descrição ou categoria"/></label><label>Categoria<select value={categoryFilter} onChange={event=>setCategoryFilter(event.target.value)}><option value="">Todas as categorias</option>{categoryOptions.map(option=><option key={option.value} value={option.value}>{option.label}</option>)}</select></label><label>Centro de custo<select value={centerFilter} onChange={event=>setCenterFilter(event.target.value)}><option value="">Todos os centros</option>{centers.map(center=><option key={center} value={center}>{center}</option>)}</select></label></div>
    {!entries.length?<Empty title="Sem lançamentos nesta seleção" description="Confira a competência e os filtros ou registre uma nova receita, despesa ou movimentação de sócio." action="Adicionar lançamento" onAction={()=>setModal({kind:'entry'})}/>:<div className="pf-table-wrap"><table className="pf-table"><thead><tr><th>Lançamento</th><th>Vencimento</th><th>Situação</th><th className="pf-number">Valor</th><th>Ações</th></tr></thead><tbody>{entries.map(entry=><tr key={entry.id}>
      <td><strong>{entry.description}</strong><small>{categoryLabel(entry.category)}{entry.costCenter?' · '+entry.costCenter:''}</small><small>Competência {dateLabel(entry.competenceDate)} · {entry.recognition==='forecast'?'Previsão':'Reconhecido'}</small>{entry.partnerId&&<small>Sócio: {state.partners.find(partner=>partner.id===entry.partnerId)?.name??'Sócio identificado'}</small>}{entry.propertyId&&<small>Imóvel: {propertyName(entry.propertyId)}</small>}</td>
      <td>{dateLabel(entry.dueDate)}{entry.settledDate&&<small>{entryStatus('settled',entry.category)} em {dateLabel(entry.settledDate)}</small>}</td><td><span className={'pf-status pf-status--'+(entry.status==='open'?'pending':entry.status)}>{entryStatus(entry.status,entry.category)}</span></td><td className="pf-number"><strong className={entryDirection(entry.category)==='out'?'pf-negative':undefined}>{money(entry.amountCents)}</strong>{entry.category==='partner_distribution'&&entry.status==='settled'&&<><small>Retenção: {money(entry.withholdingCents??0)}</small><small>Líquido pago: {money(entry.amountCents-(entry.withholdingCents??0))}</small></>}</td>
      <td><div className="pf-actions">{entry.status==='open'&&<>{!entry.operationId&&!entry.allocationId&&<button className="ps-text-button" onClick={()=>setModal({kind:'entry',id:entry.id})}>Editar</button>}<button className="ps-button ps-button--primary" onClick={()=>setModal({kind:'settle',id:entry.id})}>{settlementAction(entry.category)}</button></>}{entry.status!=='cancelled'&&!entry.operationId&&<button className="ps-text-button" onClick={()=>setModal({kind:'cancel',id:entry.id})}>Cancelar</button>}</div></td>
    </tr>)}</tbody></table></div>}
    <p className="pf-note-line">Receber e Pagar registram uma movimentação já realizada; não enviam ordens ao banco. Se ainda não houver conta cadastrada, o botão abre o cadastro e depois retorna ao lançamento.</p>
  </section>}
  {tab==='recurrences'&&<section className="pf-panel"><div className="pf-heading"><div><h2>Uma rotina financeira previsível.</h2><p>Honorários de administração, softwares, estrutura e outros compromissos mensais.</p></div><button className="ps-button ps-button--primary" onClick={()=>setModal({kind:'recurrence'})}><Plus size={16}/>Nova recorrência</button></div><Notice>MRR e ARR consideram as receitas recorrentes da EME ativas no mês atual. O aluguel bruto do proprietário não é receita da empresa. Gerar uma competência cria um lançamento para conferência.</Notice>{!state.recurrences.length?<Empty title="Organize os próximos meses" description="Comece pelas despesas fixas e pelos honorários mensais de administração. Nenhuma cobrança será enviada automaticamente." action="Cadastrar recorrência" onAction={()=>setModal({kind:'recurrence'})}/>:<div className="pf-table-wrap"><table className="pf-table"><thead><tr><th>Recorrência</th><th>Vigência</th><th>Vencimento</th><th className="pf-number">Mensal</th><th>Ações</th></tr></thead><tbody>{state.recurrences.map(recurrence=><tr key={recurrence.id}><td><strong>{recurrence.name}</strong><small>{categoryLabel(recurrence.category)}{!recurrence.active?' · Pausada':''}</small></td><td>{monthLabel(recurrence.startMonth)}<small>{recurrence.endMonth?'Até '+monthLabel(recurrence.endMonth):'Sem término definido'}</small></td><td>Dia {recurrence.dueDay}</td><td className="pf-number">{money(recurrence.amountCents)}</td><td><div className="pf-actions"><button className="ps-text-button" onClick={()=>setModal({kind:'recurrence',id:recurrence.id})}>Editar</button><button className="ps-text-button" disabled={!recurrence.active} onClick={()=>setModal({kind:'generate',id:recurrence.id})}>Gerar mês</button><button className="ps-text-button" onClick={()=>command('recurrence.save',{...recurrence,active:!recurrence.active},recurrence.active?'Recorrência pausada.':'Recorrência reativada.').catch(error=>setError(error.message))}>{recurrence.active?'Pausar':'Ativar'}</button></div></td></tr>)}</tbody></table></div>}</section>}
  {renderForm()}{toast&&<div className="ps-toast" role="status"><Check size={17}/><span>{toast}</span><button className="ps-icon" aria-label="Fechar aviso" onClick={()=>setToast('')}><X size={16}/></button></div>}
  </section>;
}
